def paired_returns(a, b):
    da, db = sorted(a), sorted(b)
    ra = [a[y] / a[x] - 1 for x, y in zip(da, da[1:])]
    rb = [b[y] / b[x] - 1 for x, y in zip(db, db[1:])]
    return list(zip(ra, rb))

def paired_returns(a, b):
    days = [d for d in a if d in b]
    return [(a[d1] / a[d0] - 1, b[d1] / b[d0] - 1)
            for d0, d1 in zip(days, days[1:])]

